import{_ as a,a0 as d,w as p,s,ao as i,I as r,x as t,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在Linux上构建 RAID 10阵列 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux上构建 RAID 10阵列 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux上构建 RAID 10阵列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux上构建 RAID 10阵列 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141009 How to set up RAID 10 for high performance and fault tolerant disk I or O on Linux","title":"如何在Linux上构建 RAID 10阵列","tag":"201412","desc":""},"relativePath":"201412/20141009 How to set up RAID 10 for high performance and fault tolerant disk I or O on Linux.md","filePath":"[post].md"}'),u={name:"201412/20141009 How to set up RAID 10 for high performance and fault tolerant disk I or O on Linux.md"},f={start:"4"};function m(I,o,D,A,g,R){const e=d("Link");return p(),s("div",null,[o[33]||(o[33]=i('<h1 id="如何在linux上构建-raid-10阵列" tabindex="-1">如何在Linux上构建 RAID 10阵列 <a class="header-anchor" href="#如何在linux上构建-raid-10阵列" aria-label="Permalink to “如何在Linux上构建 RAID 10阵列”">​</a></h1><p>RAID 10阵列（又名RAID 1+0 或先镜像后分区）通过结合RAID 0 （读写操作在多个磁盘上同时并行执行）和RAID 1（数据被完全相同地写入到两个或更多的磁盘）两者的特点实现高性能和高容错性的磁盘I/O。</p><p>这篇文章会指导你如何使用五块相同的8GB磁盘来组成一个软件RAID 10阵列。因为组成一个RAID 10阵列至少需要4块磁盘（比如，两个镜像各有一对分区组合），而且需要添加一块额外的备用磁盘以防某块主要的磁盘出错。本文也会分享一些工具，在稍后用来分析RAID阵列的性能。</p><p>注意RAID 10的优缺点和其它分区方法（在不同大小的磁盘和文件系统上）的内容不在本文讨论范围内。</p><h3 id="raid-10-阵列如何工作" tabindex="-1">Raid 10 阵列如何工作？ <a class="header-anchor" href="#raid-10-阵列如何工作" aria-label="Permalink to “Raid 10 阵列如何工作？”">​</a></h3><p>如果你需要实现一种支持I/O密集操作（比如数据库、电子邮件或web服务器）的存储解决方案，RAID 10就是你需要的。来看看为什么这么说，请看下图。</p><p><img src="https://farm4.staticflickr.com/3844/15179003008_e48806b3ef_o.png" alt=""></p><p>上图中的文件由A、B、C、D、E和F六种块组成，每一个RAID 1镜像对（如镜像1和2）在两个磁盘上复制相同的块。在这样的配置下，写操作性能会因为每个块需要写入两次而下降，每个磁盘各一次；而读操作与从单块磁盘中读取相比并未发生改变。不过这种配置的好处是除非一个镜像中有超过一块的磁盘故障，否则都能保持冗余以维持正常的磁盘I/O操作。</p><p>RAID 0的分区通过将数据划分到不同的块，然后执行同时将块A写入镜像1、将块B写入镜像2（以此类推）的并行操作以提高整体的读写性能。在另一方面，没有任何一个镜像包含构成主存的数据片的全部信息。这就意味着如果其中一个镜像故障，那么整个RAID 0组件将无法正常工作，数据将遭受不可恢复的损失。</p><h3 id="建立raid-10阵列" tabindex="-1">建立RAID 10阵列 <a class="header-anchor" href="#建立raid-10阵列" aria-label="Permalink to “建立RAID 10阵列”">​</a></h3><p>有两种建立RAID 10阵列的可行方案：复杂法（一步完成）和嵌套法（先创建两个或更多的RAID 1阵列，然后使用它们组成RAID 0）。本文会讲述复杂法创建RAID 10阵列的过程，因为这种方法能够使用偶数或奇数个磁盘去创建阵列，而且能以单个RAID设备的形式被管理，而嵌套法则恰恰相反（只允许偶数个磁盘，必须以嵌套设备的形式被管理，即分开管理RAID 1和RAID 0）。</p>',11)),r("p",null,[o[1]||(o[1]=t("假设你的机器已经安装mdadm，并运行着相应的守护进程，细节参见",-1)),n(e,{href:"http://xmodulo.com/create-software-raid1-array-mdadm-linux.html"},{default:l(()=>[...o[0]||(o[0]=[t("这篇文章",-1)])]),_:1}),o[2]||(o[2]=t("。也假设每个磁盘上已经划分出一个主分区sd[bcdef]1 （LCTT 译注：共计五块磁盘，这里是从sdb - sdf）。使用命令：",-1))]),o[34]||(o[34]=i(`<pre><code>ls -l /dev | grep sd[bcdef]
</code></pre><p>查看到的输出应该如下所示：</p><p><img src="https://farm3.staticflickr.com/2944/15365276992_db79cac82a.jpg" alt=""></p><p>然后使用下面的命令创建一个RAID 10阵列（LCTT 译注：使用了四块磁盘 bcde 创建）：</p><pre><code> # mdadm --create --verbose /dev/md0 --level=10 --raid-devices=4 /dev/sd[bcde]1 --spare-devices=1 /dev/sdf1 
</code></pre><p><img src="https://farm3.staticflickr.com/2946/15365277042_28a100baa2_z.jpg" alt=""></p><p>当阵列创建完毕后（最多花费几分钟），执行命令</p><pre><code># mdadm --detail /dev/md0
</code></pre><p>的输出应如下所示：</p><p><img src="https://farm3.staticflickr.com/2946/15362417891_7984c6a05f_o.png" alt=""></p><p>在更进一步之前需要注意以下事项。</p><ol><li><p><strong>Used Dev Space</strong>表示阵列所使用的每一块磁盘的容量。</p></li><li><p><strong>Array Size</strong>表示阵列的整体大小。RAID 10阵列的大小通过(N*C)/M计算，其中N是活跃磁盘的数目，C是每个活跃磁盘的容量，M是每一个镜像中磁盘的数目。在本文的情形下，这个值等于（4*8GiB）/2 = 16GiB。</p></li><li><p><strong>Layout</strong>是整个数据布局的详细信息。可能的布局数值如下所示。</p></li></ol><hr><ul><li><strong>n</strong>(默认选项)：代表就近（near）拷贝。一个数据块的多个拷贝在不同磁盘里有相同的偏移量。这种布局提供和RAID 0阵列相似的读写性能。</li></ul><p><img src="https://farm3.staticflickr.com/2941/15365413092_0aa41505c2_o.png" alt=""></p><ul><li><strong>o</strong>代表偏移量（offset）拷贝。块并不是在条带里面复制的，而是整个条带一起复制，但是循环会打乱，所以同一个分区中复制的块会出现在不同的磁盘。因此，一个块的后续拷贝会出现在下一个磁盘中，一个块接着一个块。为了在RAID 10阵列中使用这种布局，在创建阵列的命令中添加--layout=o2选项。</li></ul><p><img src="https://farm3.staticflickr.com/2944/15178897580_6ef923a1cb_o.png" alt=""></p><ul><li><strong>f</strong>代表远端（far）拷贝（多个拷贝在不同的磁盘中具有不同的偏移量）。这种布局提供更好的读性能但带来更差的写性能。因此，对于读远远多于写的系统来说是最好的选择。为了在RAID 10阵列中使用这种布局，在创建阵列的命令中添加--layout=f2。</li></ul><p><img src="https://farm3.staticflickr.com/2948/15179140458_4a803bb194_o.png" alt=""></p><p>跟在布局选项<strong>n</strong>、<strong>f</strong>和<strong>o</strong>后面的数字代表所需的每一个数据块的副本数目。默认值是2，但可以是2到阵列中磁盘数目之间的某个值。提供足够的副本数目可以最小化单个磁盘上的I/O影响。</p>`,20)),r("ol",f,[r("li",null,[o[4]||(o[4]=r("strong",null,"Chunk Size",-1)),o[5]||(o[5]=t("，参考",-1)),n(e,{href:"https://raid.wiki.kernel.org/"},{default:l(()=>[...o[3]||(o[3]=[t("Linux RAID wiki",-1)])]),_:1}),o[6]||(o[6]=t("的说明，是写入磁盘的最小数据单元。最佳的chunk大小取决于I/O操作的速率和相关的文件大小。对于大量的写操作，通过设置相对较大的chunk可以得到更低的开销，但对于主要存储小文件的阵列来说更小的chunk性能更好。为了给RAID 10指定一个chunk大小，在创建阵列的命令中添加",-1)),o[7]||(o[7]=r("strong",null,"--chunk=desired_chunk_size",-1)),o[8]||(o[8]=t("。",-1))])]),o[35]||(o[35]=r("p",null,"不幸的是，并没有设置一个大小就能适合全局的策略来提高性能，但可以参考下面的一些方案。",-1)),r("ul",null,[r("li",null,[o[10]||(o[10]=t("文件系统：就整体而言，",-1)),n(e,{href:"http://ask.xmodulo.com/create-mount-xfs-file-system-linux.html"},{default:l(()=>[...o[9]||(o[9]=[t("XFS",-1)])]),_:1}),o[11]||(o[11]=t("据说是最好的，当然EXT4也是不错的选择。",-1))]),o[12]||(o[12]=r("li",null,"最佳布局：远端布局能提高读性能，但会降低写性能。",-1)),o[13]||(o[13]=r("li",null,"副本数目：更多的副本能最小化I/O影响，但更多的磁盘需要更大的花费。",-1)),o[14]||(o[14]=r("li",null,"硬件：在相同的环境下，SSD比传统（机械旋转）磁盘更能带来出性能提升",-1))]),o[36]||(o[36]=i(`<h3 id="使用dd进行raid性能测试" tabindex="-1">使用DD进行RAID性能测试 <a class="header-anchor" href="#使用dd进行raid性能测试" aria-label="Permalink to “使用DD进行RAID性能测试”">​</a></h3><p>下面的基准测试用于检测RAID 10阵列（/dev/md0）的性能。</p><h4 id="_1-写操作" tabindex="-1">1. 写操作 <a class="header-anchor" href="#_1-写操作" aria-label="Permalink to “1. 写操作”">​</a></h4><p>往磁盘中写入大小为256MB的单个文件：</p><pre><code># dd if=/dev/zero of=/dev/md0 bs=256M count=1 oflag=dsync 
</code></pre><p>写入1000次512字节：</p><pre><code># dd if=/dev/zero of=/dev/md0 bs=512 count=1000 oflag=dsync 
</code></pre><p>使用dsync标记，dd可以绕过文件系统缓存，在RAID阵列上执行同步写。这个选项用于减少RAID性能测试中缓存的影响。</p><h4 id="_2-读操作" tabindex="-1">2. 读操作 <a class="header-anchor" href="#_2-读操作" aria-label="Permalink to “2. 读操作”">​</a></h4><p>从阵列中拷贝256KiB*15000（3.9 GB）大小内容到/dev/null:</p><pre><code> # dd if=/dev/md0 of=/dev/null bs=256K count=15000 
</code></pre><h3 id="使用iozone进行raid性能测试" tabindex="-1">使用Iozone进行RAID性能测试 <a class="header-anchor" href="#使用iozone进行raid性能测试" aria-label="Permalink to “使用Iozone进行RAID性能测试”">​</a></h3>`,12)),r("p",null,[n(e,{href:"http://www.iozone.org/"},{default:l(()=>[...o[15]||(o[15]=[t("Iozone",-1)])]),_:1}),o[16]||(o[16]=t("是一款文件系统基准测试工具，用来测试各种磁盘I/O操作，包括随机读写、顺序读写和重读重写。它支持将结果导出为微软的Excel或LibreOffice的Calc文件。",-1))]),o[37]||(o[37]=r("h4",{id:"在centos-rhel-7上安装iozone",tabindex:"-1"},[t("在CentOS/RHEL 7上安装Iozone "),r("a",{class:"header-anchor",href:"#在centos-rhel-7上安装iozone","aria-label":"Permalink to “在CentOS/RHEL 7上安装Iozone”"},"​")],-1)),r("p",null,[o[18]||(o[18]=t("先保证",-1)),n(e,{href:"http://xmodulo.com/how-to-set-up-rpmforge-repoforge-repository-on-centos.html"},{default:l(()=>[...o[17]||(o[17]=[t("Repoforge",-1)])]),_:1}),o[19]||(o[19]=t("可用，然后输入：",-1))]),o[38]||(o[38]=i(`<pre><code># yum install iozone 
</code></pre><h4 id="在debian-7上安装iozone" tabindex="-1">在Debian 7上安装Iozone <a class="header-anchor" href="#在debian-7上安装iozone" aria-label="Permalink to “在Debian 7上安装Iozone”">​</a></h4><pre><code># aptitude install iozone3 
</code></pre><p>下面的iozone命令会在RAID-10阵列中执行所有测试：</p><pre><code># iozone -Ra /dev/md0 -b /tmp/md0.xls 
</code></pre><ul><li><strong>-R</strong>：往标准输出生成兼容Excel的报告</li><li><strong>-a</strong>：以全自动模式运行所有的测试，并测试各种记录/文件大小。记录大小范围：4K-16M，文件大小范围：64K-512M。</li><li><strong>-b /tmp/md0.xls</strong>: 把测试结果存储到一个指定的文件中</li></ul><p>希望这篇文章对你有所帮助，如果想到任何想法或建议可能会提升RAID 10的性能，请讲出来。</p><hr>`,8)),r("p",null,[o[21]||(o[21]=t("via: ",-1)),n(e,{href:"http://xmodulo.com/setup-raid10-linux.html"},{default:l(()=>[...o[20]||(o[20]=[t("http://xmodulo.com/setup-raid10-linux.html",-1)])]),_:1})]),r("p",null,[o[25]||(o[25]=t("作者：",-1)),n(e,{href:"http://xmodulo.com/author/gabriel"},{default:l(()=>[...o[22]||(o[22]=[t("Gabriel Cánepa",-1)])]),_:1}),o[26]||(o[26]=t(" 译者：",-1)),n(e,{href:"https://github.com/KayGuoWhu"},{default:l(()=>[...o[23]||(o[23]=[t("KayGuoWhu",-1)])]),_:1}),o[27]||(o[27]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:l(()=>[...o[24]||(o[24]=[t("wxy",-1)])]),_:1})]),r("p",null,[o[30]||(o[30]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[28]||(o[28]=[t("LCTT",-1)])]),_:1}),o[31]||(o[31]=t(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:l(()=>[...o[29]||(o[29]=[t("Linux中国",-1)])]),_:1}),o[32]||(o[32]=t(" 荣誉推出",-1))])])}const k=a(u,[["render",m]]);export{T as __pageData,k as default};
